package org.pocketlore.app;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.view.*;import android.widget.*;import android.view.inputmethod.InputMethodManager;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.*;import org.json.*;

/** Bounded public UI states; no answer generation, no global font preference writes. */
public final class AccessibleInstrumentation extends Instrumentation {
 Bundle args;float scale;boolean landscape;String run,key;Activity activity;File dir;JSONObject fixture,report=new JSONObject();JSONArray checks=new JSONArray(),states=new JSONArray(),controls=new JSONArray();long left,right;String comparison;String original;Map<String,Map<String,?>> preferences=new HashMap<>();
 public void onCreate(Bundle a){args=a;start();}
 @Override public void callActivityOnCreate(Activity a,Bundle b){Configuration c=new Configuration();c.fontScale=scale;c.screenWidthDp=landscape?640:360;c.screenHeightDp=landscape?360:640;a.applyOverrideConfiguration(c);super.callActivityOnCreate(a,b);a.getWindow().setLayout(ReaderUi.dp(a,landscape?640:360),-1);}
 void ok(boolean b,String n){if(!b)throw new AssertionError(n);checks.put(n);}
 void await(BooleanSupplier b,String n)throws Exception{long until=SystemClock.elapsedRealtime()+15000;while(!b.getAsBoolean()&&SystemClock.elapsedRealtime()<until)Thread.sleep(40);ok(b.getAsBoolean(),n);}
 static Object field(Object o,String n){try{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new RuntimeException(e);}}
 static void value(Object o,String n,Object v){try{java.lang.reflect.Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}catch(Exception e){throw new RuntimeException(e);}}
 Button find(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
 Button button(String text){Button b=find(activity.getWindow().getDecorView(),text);if(b==null)throw new AssertionError("Missing action: "+text);return b;}
 void click(String text){runOnMainSync(()->button(text).performClick());waitForIdleSync();}
 void close(){if(activity!=null){Activity a=activity;runOnMainSync(a::finish);waitForIdleSync();activity=null;}}
 Activity open(Class<?> cls,Intent i)throws Exception{close();activity=startActivitySync(i.setClass(getTargetContext(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Thread.sleep(150);return activity;}
 String originals()throws Exception{JSONArray rows=new JSONArray();try(NotebookStore n=new NotebookStore(getTargetContext())){for(NotebookStore.Entry e:n.list("",false))rows.put(new JSONArray().put(e.id).put(ComparisonStore.identity(e)).put(e.note).put(e.bookmark));}return ComparisonStore.hash(rows.toString());}
 void nodes(android.view.accessibility.AccessibilityNodeInfo n,StringBuilder s){if(n==null)return;Rect r=new Rect();n.getBoundsInScreen(r);s.append(n.getClassName()).append(" | ").append(n.getText()).append(" | ").append(n.getContentDescription()).append(" | clickable=").append(n.isClickable()).append(" | ").append(r).append('\n');for(int i=0;i<n.getChildCount();i++)nodes(n.getChild(i),s);}
 void capture(String name)throws Exception{waitForIdleSync();Thread.sleep(200);String file=key+"-"+name;Bitmap b=getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(dir,file+".png"))){ok(b!=null&&b.compress(Bitmap.CompressFormat.PNG,100,out),file+"_screenshot");}StringBuilder s=new StringBuilder();nodes(getUiAutomation().getRootInActiveWindow(),s);ok(s.length()>100,file+"_nodes");Files.write(new File(dir,file+".txt").toPath(),s.toString().getBytes(StandardCharsets.UTF_8));states.put(file);}
 void action(String label)throws Exception{Button b=button(label);runOnMainSync(()->{b.requestFocus();b.requestRectangleOnScreen(new Rect(0,0,b.getWidth(),b.getHeight()),true);});waitForIdleSync();Thread.sleep(150);runOnMainSync(()->{float density=b.getResources().getDisplayMetrics().density;ok(b.getWidth()+1>=48*density&&b.getHeight()+1>=48*density,label+"_48dp");ok(b.getLayout()!=null,label+"_layout");for(int i=0;i<b.getLayout().getLineCount();i++)ok(b.getLayout().getEllipsisCount(i)==0,label+"_no_ellipsis");ok(b.getLayout().getHeight()<=b.getHeight()-b.getCompoundPaddingTop()-b.getCompoundPaddingBottom()+1,label+"_text_fits");Rect rect=new Rect();ok(b.getGlobalVisibleRect(rect)&&rect.width()>=b.getWidth()-2&&rect.height()>=b.getHeight()-2,label+"_scroll_reachable");try{controls.put(new JSONObject().put("configuration",key).put("label",label).put("width_dp",b.getWidth()/density).put("height_dp",b.getHeight()/density).put("lines",b.getLineCount()).put("enabled",b.isEnabled()).put("visible",rect.toShortString()).put("accessible_name",b.getContentDescription()==null?b.getText():b.getContentDescription()));}catch(Exception e){throw new RuntimeException(e);}});}
 double luminance(int color){double sum=0;int[] c={Color.red(color),Color.green(color),Color.blue(color)};double[] weights={.2126,.7152,.0722};for(int i=0;i<3;i++){double v=c[i]/255.;sum+=weights[i]*(v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));}return sum;}
 void contrast(TextView t,int background,String label)throws Exception{double a=luminance(t.getCurrentTextColor()),b=luminance(background);double ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05);ok(ratio>=4.5,label+"_contrast");report.getJSONArray("contrast").put(new JSONObject().put("state",key).put("label",label).put("foreground",t.getCurrentTextColor()).put("background",background).put("ratio",ratio));}
 void research()throws Exception{
  MainActivity main=(MainActivity)open(MainActivity.class,new Intent());runOnMainSync(()->((NativePanel)field(main,"nativePanel")).lowMemory());await(main::resourceIdle,"model_unloaded");ok(!main.modelReady(),"no_model_ready");EditText question=(EditText)field(main,"question");runOnMainSync(()->question.setText(fixture.optString("question")));action("Research offline  →");contrast(button("Research offline  →"),ReaderUi.TEAL,"primary_action");contrast((TextView)field(main,"status"),ReaderUi.NAVY,"research_status");capture("research-composer");
  runOnMainSync(()->{question.requestFocus();question.requestRectangleOnScreen(new Rect(0,0,question.getWidth(),question.getHeight()),true);((InputMethodManager)main.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(question,InputMethodManager.SHOW_IMPLICIT);});await(()->main.getWindow().getDecorView().getRootWindowInsets()!=null&&main.getWindow().getDecorView().getRootWindowInsets().isVisible(WindowInsets.Type.ime()),"keyboard_visible");action("Research offline  →");capture("research-keyboard");runOnMainSync(()->((InputMethodManager)main.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(question.getWindowToken(),0));await(()->!main.getWindow().getDecorView().getRootWindowInsets().isVisible(WindowInsets.Type.ime()),"keyboard_hidden");
  // Exercise actual empty-input handler; no retrieval/model request is made.
  runOnMainSync(()->{question.setText("");try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod("runSearch");m.setAccessible(true);m.invoke(main);}catch(Exception e){throw new RuntimeException(e);}});ok(question.getError()!=null,"actual_empty_question_error");capture("research-error");
  runOnMainSync(()->{question.setError(null);question.setText(fixture.optString("question"));value(main,"activeQuestion",fixture.optString("question"));try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod("resultMode",boolean.class);m.setAccessible(true);m.invoke(main,true);}catch(Exception e){throw new RuntimeException(e);}TextView a=(TextView)field(main,"answer");a.setVisibility(View.VISIBLE);a.setText("Public UI fixture — not generated output.\n"+fixture.optString("missing"));});action("Edit question");capture("research-result");click("Edit question");ok(question.getText().toString().equals(fixture.getString("question"))&&question.isShown(),"editable_question_preserved");ok(main.latestAnswer()==null,"no_answer_invocation");close();
 }
 void reader()throws Exception{SourceReaderActivity reader=(SourceReaderActivity)open(SourceReaderActivity.class,new Intent().putExtra("record",left));await(()->reader.content!=null,"source_loaded");ok(reader.entry.id==left,"source_identity");action("Close reader");contrast(reader.content,reader.cream?ReaderUi.NAVY:ReaderUi.CREAM,"reader_body");capture("reader-long-title");click("Reading options");click("Switch reading theme");contrast(reader.content,reader.cream?ReaderUi.NAVY:ReaderUi.CREAM,"reader_alternate_theme");ok(reader.getWindow().getStatusBarColor()==(reader.cream?ReaderUi.NAVY:ReaderUi.CREAM),"reader_status_theme");capture("reader-theme");runOnMainSync(()->reader.scroll.scrollTo(0,500));Thread.sleep(200);int position=reader.scroll.getScrollY();ok(position>0,"reader_scrolled");close();final SourceReaderActivity restored=(SourceReaderActivity)open(SourceReaderActivity.class,new Intent().putExtra("record",left));await(()->restored.content!=null,"reader_reopened");await(()->restored.scroll.getScrollY()==position,"reader_position_retained");action("Close reader");click("Close reader");ok(restored.isFinishing(),"reader_return");activity=null;}
 boolean idle(PersonalDocumentsActivity a){return !(boolean)field(a,"busy");}
 void documents()throws Exception{PersonalDocumentsActivity doc=(PersonalDocumentsActivity)open(PersonalDocumentsActivity.class,new Intent());action("Choose personal document");contrast((TextView)field(doc,"status"),ReaderUi.NAVY,"document_status");capture("document-import");runOnMainSync(()->doc.onActivityResult(10,Activity.RESULT_OK,new Intent().setData(android.net.Uri.parse("content://org.pocketlore.fixture.personal/invalid.json"))));await(()->idle(doc),"document_failure_finished");await(()->((TextView)field(doc,"status")).getText().toString().startsWith("Operation stopped"),"actual_document_error");action("Choose personal document");action("Cancel operation");capture("document-error");action("Return to library and search");click("Return to library and search");ok(doc.isFinishing(),"document_return");activity=null;}
 void comparison()throws Exception{ComparisonActivity grid=(ComparisonActivity)open(ComparisonActivity.class,new Intent().putExtra("comparison",comparison));await(()->grid.data!=null,"comparison_loaded");String label="Rename subject 1: "+fixture.getString("subject");action(label);ok(button(label).getText().toString().equals(label),"full_subject_action_name");capture("comparison-long-action");action("Rename dimension 1");click("Rename dimension 1");capture("comparison-edit-dialog");getUiAutomation().performGlobalAction(android.accessibilityservice.AccessibilityService.GLOBAL_ACTION_BACK);waitForIdleSync();action("Open source 1 / 1");ActivityMonitor m=addMonitor(SourceReaderActivity.class.getName(),null,false);click("Open source 1 / 1");Activity a=waitForMonitorWithTimeout(m,10000);removeMonitor(m);ok(a instanceof SourceReaderActivity,"comparison_source_open");SourceReaderActivity reader=(SourceReaderActivity)a;await(()->reader.content!=null,"comparison_source_loaded");ok(reader.entry.id==left,"comparison_exact_source");runOnMainSync(reader::finish);waitForIdleSync();action("Export comparison");capture("comparison-export");runOnMainSync(()->grid.onActivityResult(NotebookActivity.EXPORT_DOCUMENT,Activity.RESULT_CANCELED,null));ok(grid.operation.getText().toString().contains("cancelled"),"export_cancel_feedback");ok(grid.store.portable(grid.data).contains("Unknown"),"unknown_preserved");close();}
 void savePreferences(){for(String n:new String[]{"MainActivity","SourceReaderActivity"})preferences.put(n,new HashMap<>(getTargetContext().getSharedPreferences(n,0).getAll()));}
 void restorePreferences(){for(String n:preferences.keySet()){SharedPreferences.Editor e=getTargetContext().getSharedPreferences(n,0).edit().clear();for(Map.Entry<String,?> x:preferences.get(n).entrySet()){Object v=x.getValue();if(v instanceof String)e.putString(x.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof Integer)e.putInt(x.getKey(),(Integer)v);else if(v instanceof Long)e.putLong(x.getKey(),(Long)v);else if(v instanceof Float)e.putFloat(x.getKey(),(Float)v);}e.commit();ok(getTargetContext().getSharedPreferences(n,0).getAll().equals(preferences.get(n)),n+"_preferences_restored");}}
 @Override public void onStart(){boolean pass=false;try{run=args.getString("run_id");ok(run.matches("[A-Za-z0-9-]+"),"run_identity");dir=new File(getTargetContext().getFilesDir(),"accessible-check-"+run);ok(dir.mkdir(),"owned_directory");try(InputStream in=getContext().getAssets().open("cases.json")){fixture=new JSONObject(new String(in.readAllBytes(),StandardCharsets.UTF_8));}ok(ComparisonStore.hash(fixture.getString("body")).equals(fixture.getString("source_sha256")),"fixture_source_hash");original=originals();savePreferences();report.put("contrast",new JSONArray());try(NotebookStore n=new NotebookStore(getTargetContext())){left=n.add("source","T450 "+run+" "+fixture.getString("title"),"",fixture.getString("body"),"Constructed public UI fixture; date and text are not corpus facts.",false);right=n.add("source","T450 "+run+" second source","",fixture.getString("missing"),"Constructed public UI fixture",false);}ComparisonStore store=new ComparisonStore(getTargetContext());JSONObject d=store.create(left,right);comparison=d.getString("id");d.getJSONArray("subjects").getJSONObject(0).put("label",fixture.getString("subject"));ComparisonStore.addDimension(d,"A long named dimension for explicitly selected literal evidence");d.getJSONArray("dimensions").getJSONObject(0).getJSONArray("cells").put(0,store.bind(d.getJSONArray("subjects").getJSONObject(0),0,23));store.save(d);String before=store.portable(d);
  // Test-provider bytes belong to the test APK, never user files.
  Files.write(new File(getContext().getFilesDir(),"invalid.json").toPath(),fixture.getString("invalid_document").getBytes(StandardCharsets.UTF_8));
  for(float font:new float[]{1f,1.5f,2f})for(boolean wide:new boolean[]{false,true}){scale=font;landscape=wide;key=("f"+font+(wide?"-landscape":"-portrait"));ok(getUiAutomation().setRotation(wide?1:0),"temporary_rotation");Thread.sleep(350);research();reader();documents();comparison();ok(store.portable(store.load(comparison)).equals(before),"comparison_bindings_retained");}pass=true;
 }catch(Throwable e){try{report.put("error",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}}finally{try{close();ok(getUiAutomation().setRotation(-2),"rotation_unfrozen");restorePreferences();if(comparison!=null)new ComparisonStore(getTargetContext()).remove(comparison);try(NotebookStore n=new NotebookStore(getTargetContext())){for(long id:new long[]{left,right})if(id>0){ok(n.get(id).title.startsWith("T450 "+run),"owned_cleanup");n.remove(id);}}if(original!=null)ok(originals().equals(original),"original_records_retained");}catch(Throwable e){pass=false;try{report.put("restore_error",e.toString());}catch(Exception ignored){}}try{report.put("status",pass?"PASS":"FAIL").put("run_id",run).put("source_manifest_sha256",args.getString("source_manifest_sha256")).put("checks",checks).put("states",states).put("controls",controls);Files.write(new File(dir,"report.json").toPath(),report.toString(2).getBytes(StandardCharsets.UTF_8));Bundle b=new Bundle();b.putString("accessible_receipt",report.toString());finish(pass?Activity.RESULT_OK:Activity.RESULT_CANCELED,b);}catch(Exception e){finish(Activity.RESULT_CANCELED,new Bundle());}}}
}
